INSERT INTO "nkjv" ("verseid","book","chapter","versenumber","verse") VALUES (3929,'Num',7,78,'On the twelfth day Ahira the son of Enan, leader of the children of Naphtali, presented an offering.');
INSERT INTO "nkjv" ("verseid","book","chapter","versenumber","verse") VALUES (3930,'Num',7,79,'His offering was one silver platter, the weight of which was one hundred and thirty shekels, and one silver bowl of seventy shekels, according to the shekel of the sanctuary, both of them full of fine flour mixed with oil as a grain offering;');
